<?php $crumbs = [['label'=>'خانه','href'=>'/'], ['label'=>'پشتیبانی']]; ?>
<section class="page-banner"><div class="container"><div class="eyebrow">پشتیبانی</div><h1>درخواست و <em>پیگیری</em></h1><p>پرسش خود را ثبت کنید؛ پاسخ را در همین پنل ببینید.</p></div></section><section class="section container support-layout"><div class="support-form-card"><h2>ثبت درخواست جدید</h2><form method="post" action="/support" class="form-stack"><?= csrfField() ?><label>موضوع<input name="subject" required minlength="4" maxlength="180"></label><label>رویداد مرتبط (اختیاری)<select name="event_id"><option value="">انتخاب نشده</option><?php $s=db()->prepare("SELECT e.id,e.title FROM events e JOIN registrations r ON r.event_id=e.id WHERE r.user_id=? AND r.status='confirmed' ORDER BY e.starts_at_utc DESC"); $s->execute([(int)$user['id']]); foreach($s->fetchAll() as $e): ?><option value="<?= (int)$e['id'] ?>"><?= h($e['title']) ?></option><?php endforeach; ?></select></label><label>شرح درخواست<textarea name="body" required minlength="10" maxlength="5000" rows="6"></textarea></label><button class="btn btn-primary" type="submit">ارسال درخواست</button></form></div><div><h2>تیکت‌های من</h2><?php if ($tickets): ?><div class="ticket-list"><?php foreach($tickets as $t): ?><a class="support-ticket" href="/support/<?= (int)$t['id'] ?>"><span><b><?= h($t['subject']) ?></b><small><?= h($t['event_title'] ?: 'عمومی') ?> · <?= h(jalaliDate($t['updated_at'])) ?></small></span><span class="status status-<?= h($t['status']) ?>"><?= h($t['status']) ?></span></a><?php endforeach; ?></div><?php else: ?><div class="empty-box compact"><p>تیکتی ثبت نکرده‌اید.</p></div><?php endif; ?></div></section>
